import{z as o,x as d,o as t,c as p,q as l,j as s,D as E,d as r,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"ART 在数据库","description":"","frontmatter":{"title":"ART 在数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/art-index-db.md","filePath":"cs/art-index-db.md","lastUpdated":1791413859000}'),B={name:"cs/art-index-db.md"};function T(m,a,R,D,C,c){const n=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="art-在数据库" tabindex="-1">ART 在数据库 <a class="header-anchor" href="#art-在数据库" aria-label="Permalink to &quot;ART 在数据库&quot;">​</a></h1><div class="epigraph"><p>自适应基数树按键字节下降，节点类型随扇出变；范围扫描保序，点查不先搅哈希。</p><footer>—— 据 Leis, Kemper and Neumann, The Adaptive Radix Tree, ICDE 2013；计算机栏 ART 课接到引擎</footer></div><p><a href="/cs/bw-tree">上一课</a>用 delta 链改逻辑 B 页。本课不 CAS 映射表。缺口是另一主存有序索引：计算机课已讲 <a href="/cs/art-adaptive-radix">ART 结构</a>（Node4/16/48/256、前缀压缩）。数据库进阶把它接到缓冲、事务与范围扫描：二级索引、连接哈希的替代、或主存 OLTP 的主键树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>B+ 面向页与磁盘；哈希索引无序。主存里 ART 用键的真实字节，扇出自适应，前缀压缩吃掉一元路径。缺口是<strong>引擎合同</strong>：并发（乐观锁、ROWEX）、值存在叶子还是 RID、与 MVCC 版本如何挂、检查点如何扫树。</p><p>范围：<code>WHERE k BETWEEN</code> 沿有序孩子走，比哈希友好。等值连接可用 ART 当内表索引 NLJ，或当构建侧的有序结构。本课不重推节点升级算法。</p><p><span class="marginnote">Leis, Kemper, Neumann, ICDE 2013。HyPer 等主存库使用。整数键大端化以保序。本课不抄实验表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主键：键→行指针或行内嵌。二级：键→RID 列表。并发：读乐观验证版本计数，写锁节点或用 ROWEX 读写锁变体。崩溃：ART 在易失内存则靠日志重放重建，或定期序列化；与 Bw 的映射表落盘问题同类。</p><p><span class="marginnote">「RID」就是「行标识符」——一条索引键对应的那行记录住在表里哪个位置的地址条。二级索引查到的是 RID 列表，拿到之后通常还要「回表」按 RID 去取整行，所以二级索引查找常是两跳而不是一跳。</span></p><p>与缓冲池：纯主存 ART 不经页帧；混合存储把冷键落 B+，热键 ART，是工程分层，本课点名。</p>',11)),(t(),s(A,null,{default:E(()=>[i(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E9%94%AE%E5%AD%97%E8%8A%82%22%5D%20--%3E%20ART%5B%22%E8%87%AA%E9%80%82%E5%BA%94%E8%8A%82%E7%82%B9%22%5D%0A%20%20ART%20--%3E%20EQ%5B%22%E7%82%B9%E6%9F%A5%22%5D%0A%20%20ART%20--%3E%20RNG%5B%22%E6%9C%89%E5%BA%8F%E8%8C%83%E5%9B%B4%22%5D%0A%20%20ART%20--%3E%20TX%5B%22%E7%89%88%E6%9C%AC%20%2F%20%E4%B9%90%E8%A7%82%E5%B9%B6%E5%8F%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"缓存行：Node16 可用 SIMD 比较，这是 CPU 课与数据库执行的交界，不是另一查询语言。延迟物化：叶子可只存 RID。学习索引后课用模型代替树下降；ART 仍是精确结构，最坏路径有界。",-1)),a[5]||(a[5]=e("p",null,"锁：不要把 ART 节点 latch 与行锁混淆，pin-latch 课的分层仍成立——若 ART 不在页里，则节点锁替代页 latch。",-1)),a[6]||(a[6]=e("p",null,"乐观并发下一次读到底怎么走？答案是「先干活，结束时对账」：",-1)),(t(),s(A,null,{default:E(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%AE%B0%E4%B8%8B%E6%A0%B9%E8%8A%82%E7%82%B9%E7%89%88%E6%9C%AC%E5%8F%B7%20v0%22%5D%20--%3E%20D%5B%22%E4%B8%8D%E5%8A%A0%E9%94%81%E6%B2%BF%E6%A0%91%E4%B8%8B%E9%99%8D%E5%88%B0%E5%8F%B6%E5%AD%90%22%5D%0A%20%20D%20--%3E%20C%5B%22%E9%87%8D%E8%AF%BB%E6%A0%B9%E8%8A%82%E7%82%B9%E7%89%88%E6%9C%AC%E5%8F%B7%22%5D%0A%20%20C%20--%3E%20V%7B%22%E7%89%88%E6%9C%AC%E4%BB%8D%E6%98%AF%20v0%20%3F%22%7D%0A%20%20V%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E8%AF%BB%E5%8F%96%E6%9C%89%E6%95%88%20%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%22%5D%0A%20%20V%20--%3E%7C%22%E5%90%A6%20%E5%8F%98%E4%BA%86%22%7C%20R%5B%22%E6%9C%89%E5%B9%B6%E5%8F%91%E5%86%99%E4%BB%8B%E5%85%A5%20%E4%BB%8E%E5%A4%B4%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比：乐观读像超市小票复核——进门前记下价目表版本号，挑完东西结账时再核对一眼，没变就直接走人，变了说明有人中途改价，重新挑一遍。读多写少的负载里几乎不用等锁，这正是主存 OLTP 看重它的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 LSM 的 memtable 用 ART 还是跳表——LSM 下一课。也不把 ART 当磁盘主键的默认。字符串极长前缀的内存要压，极端时退化。</p><p><span class="marginnote">常见误区：初学者容易以为「换上内存索引就万事大吉」。ART 住在易失内存里，掉电即失；每次重启都得靠日志重放或定期序列化把树重建出来，这一半恢复成本省不掉，评估方案时要把它算进去。</span></p><p>后课默认：主存有序点查与范围可用 ART。LSM 与 compaction：写优化路径把随机写变成顺序文件，索引形状又变。</p><p>ART 保键序；哈希 memtable 不保，范围扫描要另结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据库里 ART 作主存有序索引，结构见计算机课，合同是并发与持久。</li><li>范围扫描是相对哈希的理由。</li><li>LSM 与 compaction 下一课：写放大换顺序写。</li><li>出处：Leis, Kemper, Neumann, ICDE 2013；ART 结构课。</li></ul>',8))])}const f=o(B,[["render",T]]);export{u as __pageData,f as default};
